def cond(gr,s,q,n,**kw):return add(gr,'conditions',s,q,kw.pop('statement',('Source diagnosis: '+n+'.')),name=n,verification_status=kw.pop('verification_status','confirmed'),**kw)
def sym(gr,s,q,n,**kw):return add(gr,'symptoms_function',s,q,kw.pop('statement',('No ' if kw.get('assertion')=='absent' else '')+n+'.'),name=n,kind=kw.pop('kind','symptom'),**kw)
def proc(gr,s,q,n,**kw):return add(gr,'procedures_devices',s,q,kw.pop('statement',n+' was performed.'),name=n,kind=kw.pop('kind','procedure'),action=kw.pop('action','completed'),**kw)
def med(gr,s,q,n,**kw):return add(gr,'medications',s,q,kw.pop('statement',n+': '+str(kw.get('dose_text') or kw.get('regimen') or 'documented treatment')+'.'),name=n,action=kw.pop('action','administered'),**kw)
def out(gr,s,q,event,text,**kw):return add(gr,'outcomes',s,q,text+'.',event=event,text_value=text,**kw)
